// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2010, "2-3", [{"author":"И. Рубанов","question":"Между какими двумя буквами в русском алфавите стоит ещё одна буква?","choices":["между <em>Б</em> и <em>В</em>","между <em>В</em> и <em>Г</em>","между <em>Г</em> и <em>Д</em>","между <em>Д</em> и <em>Е</em>","между <em>Е</em> и <em>Ж</em>."],"key":"Д","review":["Порядок букв","Произнеси начало алфавита до «Ж». После «Д» идут «Е», «Ё», «Ж».","Между «Е» и «Ж» стоит «Ё». Остальные пары из списка состоят из букв-соседок."]},{"author":"Л. Фёдорова","question":"Что не разгадывают?","choices":["ребус","кроссворд","головоломку","скороговорку","шараду."],"key":"Г","review":["Что разгадывают","В ребусе, кроссворде, головоломке и шараде есть спрятанный ответ. Его и нужно разгадать.","Скороговорку стараются произнести быстро и чётко. Так тренируют речь. Скрытого ответа в ней нет."]},{"author":"О. Шеманаева","question":"Слово, которым нельзя считать, — это","choices":["<em>пара</em>","<em>тройка</em>","<em>четвёрка</em>","<em>пятёрка</em>","<em>шестерёнка</em>."],"key":"Д","review":["Слова для счёта","Пара — два предмета, тройка — три, четвёрка — четыре, пятёрка — пять. Так можно сосчитать предметы в группе.","Шестерёнка — зубчатое колёсико механизма. Группу из шести предметов можно назвать шестёркой."]},{"author":"Методкомиссия","question":"Что за зверь, скажите, братцы,\nМожет сам в себя забраться?\nНа эту языковую загадку Екатерины Серовой часто дают ответ <em>улитка</em> или <em>черепаха</em>. Но правильный ответ на неё —","choices":["<em>собака</em>","<em>корова</em>","<em>норка</em>","<em>лиса</em>","<em>белка</em>."],"key":"В","review":["Зверь из загадки","Ищи название зверя, которое одновременно подходит для названия его укрытия. Тогда «в себя» можно понять как «в место с таким же названием».","Норка — зверёк, а норка в другом смысле — маленькая нора. Норка-зверёк действительно может забраться в норку."]},{"author":"Б. Иомдин","question":"Что обычно не носят?","choices":["носки","нос","усы","очки","воду."],"key":"Б","review":["Что обычно носят","Носки и очки надевают, воду переносят в ведре, а «носить усы» означает иметь усы и не сбривать их.","Нос — часть тела, и про него в обычной речи не говорят, что его носят. «Водить за нос» и «задирать нос» — другие выражения."]},{"author":"И. Рубанов","question":"<em>Кошка — кот</em>, <em>коза — козёл</em>, <em>овца — баран</em>, <em>корова</em> — …?","choices":["<em>телёнок</em>","<em>бык</em>","<em>говядина</em>","<em>сено</em>","<em>коровник</em>."],"key":"Б","review":["Пары животных","Кот, козёл и баран — самцы животных, которые перечислены первыми в каждой паре.","Самца коровы называют быком. Телёнок — детёныш, поэтому он подходит в пару по другому правилу."]},{"author":"И. Рубанов","question":"Маша с Дашей увидели змею, испугались и дружно вскрикнули:","choices":["<em>Ой!</em>","<em>Ну!</em>","<em>Эй!</em>","<em>Ха!</em>","<em>Но!</em>"],"key":"А","review":["Как вскрикнули девочки","Девочки испугались неожиданной встречи. Им нужен короткий возглас испуга или удивления.","Так обычно восклицают «Ой!». «Эй!» окликают, а «Но!» говорят, например, когда понукают лошадь."]},{"author":"И. Иткин","question":"Какое из этих слов <strong>не</strong> может означать ‘соревнование’?","choices":["<em>забег</em>","<em>заезд</em>","<em>заплыв</em>","<em>заскок</em>","все эти слова могут означать ‘соревнование’."],"key":"Г","review":["Спортивное соревнование","Бегуны участвуют в забеге, гонщики — в заезде, пловцы — в заплыве. У этих слов есть спортивный смысл.","Заскок — каприз или странная выходка. Этим словом соревнование не называют."]},{"author":"О. Шеманаева","question":"В книге Эдуарда Успенского «Дядя Фёдор, пёс и кот» почтальон Печкин первый раз появляется так:\n«<em>А навстречу им какой-то дядя бежит. Румяный такой, в шапке. Лет пятидесяти с хвостиком.</em> (<em>Это не дядя с хвостиком, а _____ у него с хвостиком.</em>)». Какое слово в последней фразе мы заменили чертой?","choices":["<em>бег</em>","<em>возраст</em>","<em>рост</em>","<em>румянец</em>","<em>шапка</em>."],"key":"Б","review":["Печкин с хвостиком","Прочитай «лет пятидесяти с хвостиком». Здесь «хвостик» означает, что Печкину чуть больше пятидесяти лет.","Число прожитых лет — возраст. Именно его автор в шутку называет «с хвостиком»."]},{"author":"Е. Вельмезова","question":"Название какого нужного в хозяйстве предмета происходит от немецкого слова, означающего ‘змея’?","choices":["<em>плоскогубцы</em>","<em>топор</em>","<em>ножницы</em>","<em>шланг</em>","<em>пила</em>."],"key":"Г","review":["Немецкое слово в хозяйстве","Представь змею: она длинная и может изгибаться. Ищи предмет, который похож на неё по форме и гибкости.","Подходит шланг. По-немецки Schlange означает «змея», и от этого слова произошло русское название гибкой трубки."]},{"author":"Е. Муравенко","question":"Что не поместится в пенале?","choices":["[ЛИНЕЙКА]","[КАРАНДАШ]","[ТОЧИЛКА]","[РУЧКА]","[ПОРТФЕЛЬ]."],"key":"Д","review":["Ребусы про пенал","В варианте Д буквы «т» лежат на «р». Читай «по р т» и прибавь «ф» и название дерева «ель»: получается «портфель».","Карандаш, точилка, линейка и ручка — принадлежности, которые кладут в пенал. Портфель крупнее: в него самого можно положить пенал."],"figure":{"options":[{"src":"assets/medvezhonok/2010/2-3-11-1.webp","width":162,"height":76,"pixelWidth":162,"pixelHeight":76,"description":"Шина с заменой Ш на Л и запятой после неё, лейка с запятой перед ней"},{"src":"assets/medvezhonok/2010/2-3-11-2.webp","width":191,"height":73,"pixelWidth":191,"pixelHeight":73,"description":"Игральная карта с двумя запятыми после неё, бант с запятой с каждой стороны и душ с заменой У на А"},{"src":"assets/medvezhonok/2010/2-3-11-3.webp","width":148,"height":67,"pixelWidth":148,"pixelHeight":67,"description":"Число 100 с запятой перед ним, затем вилка с заменой В на Ч"},{"src":"assets/medvezhonok/2010/2-3-11-4.webp","width":141,"height":66,"pixelWidth":141,"pixelHeight":66,"description":"Руль с двумя запятыми после него, бочка с двумя запятыми перед ней"},{"src":"assets/medvezhonok/2010/2-3-11-5.webp","width":143,"height":69,"pixelWidth":143,"pixelHeight":69,"description":"Маленькие Т на большой Р, затем ф и ель"}],"onlyPictures":true}},{"author":"Л. Фёдорова","question":"В известном мультфильме Волк говорит, когда Заяц убегает от него: «Ну, Заяц, погоди!» Как понять слова Волка? Он","choices":["просит Зайца подождать","советует не торопиться","шутит","жалуется","угрожает."],"key":"Д","review":["Возглас Волка","Волк говорит это Зайцу, который от него уже убежал. Представь, с каким намерением он кричит вслед.","«Погоди!» здесь означает «Вот я тебя ещё поймаю!». Волк грозит Зайцу неприятностями."]},{"author":"И. Рубанов и Л. Фёдорова","question":"Школьная оценка, которую в прежние времена называли <em>посредственно</em>, — это","choices":["пятёрка","четвёрка","тройка","двойка","единица."],"key":"В","review":["Старое название оценки","Слово «посредственно» описывает результат среднего качества. В пятибалльной шкале средняя оценка находится между двумя нижними и двумя верхними.","Посчитай оценки по порядку от одного до пяти. Ровно посередине стоит тройка, её и называли «посредственно»."]},{"author":"О. Шеманаева","question":"В стихотворении Даниила Хармса таксик говорит бульдогу:\n«Пора мне на свидание,\nУж восемь без пяти.\nКак поздно! До свидания!\nСидите на цепи!»\nА сколько было времени?","choices":["восемь часов пять минут","семь часов пятьдесят пять минут","пять часов восемь минут","четыре часа пятьдесят две минуты","три часа."],"key":"Б","review":["Таксик смотрит на часы","«Восемь без пяти» означает, что до восьми часов остаётся пять минут. Восемь ещё не наступило.","Вычти пять минут из 8:00. В предыдущем часе это 55-я минута, значит, на часах будет 7:55."]},{"author":"Н. Валеева","question":"Даны прилагательные: <em>голодный</em>, <em>здоровый</em>, <em>красный</em>, <em>упрямый</em>. Кто лишний?","choices":["бык","волк","заяц","осёл","рак."],"key":"В","review":["Сравнения с животными","Вспомни сравнения «голодный как волк», «здоровый как бык», «красный как рак» и «упрямый как осёл».","Зайца обычно берут для сравнения с тем, кто труслив или быстр. Ни одного из этих признаков в списке нет."]},{"author":"О. Шеманаева","question":"В известном предложении из букваря «<em>Мама мыла раму</em>» не сказано, какую раму мама мыла. Что мама точно не могла мыть?","choices":["тарелку","велосипед","окно","зеркало","картину."],"key":"А","review":["Какую раму мыла мама?","Рама бывает у окна и у велосипеда, а в раму вставляют зеркало и картину.","Тарелка может иметь ободок или бортик, но рамы у неё нет. Поэтому она точно не подходит к фразе из букваря."]},{"author":"Н. Добрушина","question":"Маленького Юлика зовут так же, как его дедушку. Значит, они с дедушкой","choices":["<em>ровесники</em>","<em>именинники</em>","<em>одноимённики</em>","<em>однофамильцы</em>","<em>тёзки</em>."],"key":"Д","review":["Юлик и дедушка","У них совпадают имена. «Ровесники» были бы одного возраста, а «однофамильцы» — с одной фамилией.","Людей с одинаковым именем называют тёзками. Юлик и дедушка — тёзки, даже когда они разных поколений."]},{"author":"Н. Добрушина","question":"Юлик и Ося любят играть друг с другом в пластилиновых солдатиков. У Оси двести семьдесят один…","choices":["…таких солдатиков","…такого солдатика","…такой солдатик","…такие солдатики","…штук таких солдатиков."],"key":"В","review":["Пластилиновые солдатики","Число заканчивается отдельным словом «один». Именно оно определяет форму следующего существительного, как в «двадцать один рубль».","Скажи «один такой солдатик», а затем верни всё число: «двести семьдесят один такой солдатик». И «такой», и «солдатик» стоят в единственном числе."]},{"author":"В. Черванёва","question":"Какое слово лишнее по смыслу?","choices":["<em>пахарь</em>","<em>пекарь</em>","<em>лекарь</em>","<em>глухарь</em>","<em>звонарь</em>."],"key":"Г","review":["Пять слов на «-арь»","Пахарь пашет, пекарь печёт, лекарь лечит, звонарь звонит в колокола. По каждому слову можно узнать занятие человека.","Глухарь — лесная птица. Это название животного, поэтому в группе названий занятий оно лишнее."]},{"author":"И. Иткин","question":"В каком слове есть приставка?","choices":["скрипка","скрепка","скобка","склянка","сковородка."],"key":"Б","review":["Слова, начинающиеся на С","Сравни «скрипку» со «скрипом», «скобку» со «скобой», «склянку» со «скляночкой», а «сковородку» со «сковородой». В этих парах начальная С входит в общий корень.","Скрепкой скрепляют листы. Сравни «скрепить» и «крепить»: «креп-» — корень, а начальная «с-» — приставка."]},{"author":"А. Пиперски","question":"Златопуст Локонс, герой романа Дж. К. Роулинг «Гарри Поттер и Тайная комната», написал книги «Тропою троллей», «Победа над привидением» и «Духи на дорогах». Какая из перечисленных ниже книг тоже написана им?","choices":["«Встречи с вампирами»","«Великаны среди нас»","«Бой с единорогом»","«Леший на опушке»","«Война с саламандрами»."],"key":"А","review":["Книги Златопуста Локонса","В названиях повторяются согласные в начале главных слов: «Тропою троллей» — «т», «Победа над привидением» — «п», «Духи на дорогах» — «д».","Тот же приём есть в «Встречах с вампирами»: и «встречи», и «вампиры» начинаются на «в». Остальные варианты такой пары не дают."]},{"author":"С. Бурлак","question":"Назовём букву в слове «заменимой», если её можно заменить другой буквой так, чтобы снова получилось осмысленное слово. Например, буква <strong><em>ж</em></strong> в слове <em>лужа</em> — заменимая, потому что её можно заменить буквой <strong><em>н</em></strong> и получить слово <em>луна</em>. Сколько заменимых букв в слове <em>клан</em>?","choices":["ни одной","одна","две","три","четыре."],"key":"Д","review":["Замены в слове «клан»","Поменяй первую букву «к» на «п» и получи «план». Вторую, «л», можно заменить на «р»: получится «кран».","На третьем месте меняй «а» на «о» и получай «клон», на четвёртом меняй «н» на «д» и получай «клад». Пример нашёлся для каждой из четырёх букв."]},{"author":"Н. Валеева","question":"В какой из данных ниже пар слова состоят из разного количества <strong>звуков</strong>?","choices":["<em>он — я</em>","<em>мне — ей</em>","<em>её — его</em>","<em>им — вам</em>","<em>мною — тобой</em>."],"key":"Г","review":["Звуки в парах слов","Считай звуки. «Он» и «я» дают по два, «мне» и «ей» по три, «её» и «его» по четыре, «мною» и «тобой» по пять.","В паре «им — вам» слышатся [и], [м] в первом слове и [в], [а], [м] во втором. Только тут числа разные: два и три."]},{"author":"Б. Иомдин и А. Пиперски","question":"В книге А. Шибаева «Язык родной, дружи со мной» четыре из этих пяти стихотворений напечатаны в одной главе, а одно — в другой. Какое?","choices":["Мягкий знак живёт беспечно —\nОн без кепки ходит вечно.","Синеет море перед нами.\nЛетают майки над волнами.","Миша дров не напилил —\nПечку кепками топил.","Тает снег. Течёт ручей.\nНа ветвях полно врачей.","Мы собирали васильки.\nНа головах у нас щенки."],"key":"А","review":["Стихи из двух глав","В четырёх стихах нелепое слово можно исправить одной буквой: «майки» → «чайки», «кепками» → «щепками», «врачей» → «грачей», «щенки» → «венки».","Шутка о мягком знаке без кепки устроена иначе: говорят о самой букве. Здесь нет случайно заменённой буквы, поэтому стихотворение из другой главы."]},{"author":"И. Рубанов","question":"Художник Тюбик посадил у своего дома малину, сирень, розы и ...","choices":["астры","бамбук","вишни","георгины","клёны."],"key":"В","review":["Посадки художника Тюбика","Малина даёт название малиновому цвету, сирень — сиреневому, розы — розовому. Подумай, от какого растения в списке тоже назван цвет.","Вишни напоминают о вишнёвом цвете — тёмно-красном. Так у художника получается целый набор оттенков."]},{"author":"С. Переверзева","question":"Какое слово пропущено в отрывке из написанного Юрием Энтиным «Романса черепахи Тортилы»?\nЗатянулась … тиной\nГладь старинного пруда.\nАх, была, как Буратино,\nЯ когда-то молода!","choices":["<em>старой</em>","<em>мутной</em>","<em>ветхой</em>","<em>бурой</em>","<em>вязкой</em>."],"key":"Г","review":["Песня черепахи Тортилы","Пропущенное слово относится к тине, которая закрыла старый пруд. В песне этим словом назван её цвет.","Юрий Энтин написал «Затянулась бурой тиной / Гладь старинного пруда». «Бурой» значит коричневатой, как тина в старом пруду."]},{"author":"Б. Иомдин","question":"Какое из сочетаний слов (А)–(Г) имеет смысл?","choices":["<em>приплыло ходила</em>","<em>приползло бегала</em>","<em>пришло ползала</em>","<em>прибежало плавала</em>","все сочетания слов (А)–(Г) бессмысленны."],"key":"В","review":["Сочетание из двух слов","Все первые слова похожи на глаголы, и почти все вторые тоже. Найди второе слово, которое можно прочитать как название количества.","«Ползала» — половина зала, а здесь ещё и половина людей, которые в нём помещаются. «Пришло ползала» значит, что зал заполнился наполовину."]},{"author":"А. Сомин","question":"Болгарский язык родствен русскому. Какая игра по-болгарски называется <em>прескочи-кобила</em>?","choices":["классики","чехарда","прятки","жмурки","казаки-разбойники."],"key":"Б","review":["Игра по-болгарски","Разбери название на похожие русские части: «прескочи» похоже на «перескочи», «кобила» — на «кобыла».","В чехарде игрок наклоняется и изображает лошадку, а другие перепрыгивают через него. Это и подсказало болгарское название."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
